import { HubConnectionBuilder } from "@microsoft/signalr";
import { Activity, ArchiveRestore, Boxes, CirclePlay, CircleStop, Download, FolderArchive, Gamepad2, HeartPulse, LogOut, RefreshCw, Save, Search, Settings2, TerminalSquare, Trash2, Upload, Users } from "lucide-react";
import { type ChangeEvent, type FormEvent, useCallback, useEffect, useState } from "react";
import { Button } from "./components/ui/button";
import { Card } from "./components/ui/card";

type State = "stopped" | "starting" | "running" | "stopping" | "failed";
type Status = { state: State; processId?: number; message?: string };
type ResourceSettings = { frequency: string; size: string; richness: string };
type MapGeneration = { seed?: number; width: number; height: number; water: string; startingArea: string; terrainSegmentation: string; peacefulMode: boolean; ironOre: ResourceSettings; copperOre: ResourceSettings; stone: ResourceSettings; coal: ResourceSettings; uraniumOre: ResourceSettings; crudeOil: ResourceSettings; trees: ResourceSettings; enemyBase: ResourceSettings; evolutionTime: number; evolutionPollution: number; evolutionDestroy: number; enemyExpansionEnabled: boolean; enemyExpansionMinDistance: number; enemyExpansionMaxDistance: number; settlerGroupMinSize: number; settlerGroupMaxSize: number; expansionMinCooldown: number; expansionMaxCooldown: number; cliffElevationInterval: number; cliffElevationOffset: number; cliffRichness: string };
type Settings = { serverName: string; description: string; maxPlayers: number; visibilityPublic: boolean; autosaveMinutes: number; activeSave?: string; channel: "stable" | "experimental"; activeVersion?: string; backupIntervalHours: number; backupRetention: number; timeZone: string; mapGeneration: MapGeneration };
type UpdateStatus = { availableVersion?: string; checkedVersion?: string; checkedAt: string; error?: string };
type VersionCatalog = { stable?: { headless?: string }; experimental?: { headless?: string } };
type SystemHealth = { checkedAt: string; uptimeSeconds: number; workingSetBytes: number; dataFreeBytes?: number; dataTotalBytes?: number; saveCount: number; backupCount: number; versionCount: number; modFileCount: number; databasePresent: boolean };
type MaintenanceStatus = { checkedAt: string; backupIntervalHours: number; backupRetention: number; lastScheduledBackup?: string; nextScheduledBackup?: string; lastUpdateCheck?: string; nextUpdateCheck?: string };
type Mod = { name: string; version: string; enabled: boolean; dependencies?: string[]; source?: "portal" | "local"; archiveFileName?: string; sha256?: string; factorioVersionRequirement?: string };
type ModUpdateInfo = { name: string; installedVersion: string; latestVersion?: string; updateAvailable: boolean; missingDependencies: string[]; downloadUrl?: string };
type ModProfile = { name: string; mods: Array<{ name: string; version: string; enabled: boolean }>; createdAt: string; updatedAt: string };
type PortalMod = { name: string; title?: string; summary?: string; latest_release?: { version?: string } };
type PortalSearchResponse = { results: PortalMod[]; pagination?: { count?: number; pageCount?: number } };
type ModRecovery = { pending: boolean; message?: string; quarantinedFiles: string[]; startedAt?: string };
type ModPreflight = { operation: string; allowed: boolean; requiresBackup: boolean; activeSave?: string; activeVersion?: string; plannedMods: Mod[]; blockers: string[]; warnings: string[]; downloads: string[] };
type Tab = "overview" | "settings" | "versions" | "mods" | "saves" | "players" | "logs" | "health" | "users" | "audit";
type Me = { csrfToken: string; uid?: string; name?: string; role?: "owner" | "admin" | "viewer" };
type User = { id: string; username: string; role: "owner" | "admin" | "viewer" };
type AuditEvent = { id: number; occurredAtUtc: string; action: string; targetType: string; outcome: string; actorUserId?: string };
type LivePlayer = { name: string; onlineSinceSeconds?: number };
type Action = (path: string, init?: RequestInit) => Promise<boolean>;
let csrf = "";
class ApiError extends Error { constructor(public readonly status: number, message: string) { super(message); this.name = "ApiError"; } }
let onUnauthorized: (() => void) | undefined;
async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.method && !["GET", "HEAD"].includes(init.method)) headers.set("X-CSRF-Token", csrf);
  if (init.body && !(init.body instanceof FormData)) headers.set("Content-Type", "application/json");
  const response = await fetch(path, { ...init, headers, credentials: "same-origin" });
  if (!response.ok) {
    if (response.status === 401) onUnauthorized?.();
    const payload = await response.json().catch(() => undefined) as { error?: string; detail?: string } | undefined;
    throw new ApiError(response.status, payload?.error ?? payload?.detail ?? response.statusText);
  }
  if (response.status === 204) return undefined as T;
  const text = await response.text();
  if (!text.trim()) return undefined as T;
  try { return JSON.parse(text) as T; } catch { throw new ApiError(response.status, "Server returned an invalid JSON response."); }
}

function Auth({ configured, done }: { configured: boolean; done: () => void }) {
  const [password, setPassword] = useState(""); const [code, setCode] = useState(""); const [username, setUsername] = useState(configured ? "admin" : ""); const [token, setToken] = useState(""); const [error, setError] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); try { const result = configured ? await api<{ csrfToken: string }>("/api/auth/login", { method: "POST", body: JSON.stringify({ username: username || "admin", password }) }) : await api<{ csrfToken: string }>("/api/auth/setup", { method: "POST", body: JSON.stringify({ code, password, factorioUsername: username || null, factorioToken: token || null }) }); csrf = result.csrfToken; done(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Authentication failed."); } }
  return <main className="mx-auto flex min-h-screen max-w-md items-center px-5"><Card className="w-full space-y-5"><div className="flex items-center gap-3"><Gamepad2 className="h-9 w-9 text-yellow-400" /><div><h1 className="text-xl font-bold">Factorio Server Manager</h1><p className="text-sm text-zinc-400">{configured ? "Sign in to manage this server" : "Complete one-time setup"}</p></div></div><form onSubmit={submit} className="space-y-3">{configured ? <label className="block text-sm">Username<input value={username} onChange={event => setUsername(event.target.value)} required /></label> : <><label className="block text-sm">Setup code<input value={code} onChange={event => setCode(event.target.value)} required /></label><label className="block text-sm">Factorio username<input value={username} onChange={event => setUsername(event.target.value)} /></label><label className="block text-sm">Factorio token<input type="password" value={token} onChange={event => setToken(event.target.value)} /></label></>}<label className="block text-sm">Account password<input type="password" minLength={8} value={password} onChange={event => setPassword(event.target.value)} required /><span className="mt-1 block text-xs text-zinc-500">อย่างน้อย 8 ตัวอักษร</span></label>{error && <p className="rounded bg-red-950 p-3 text-sm text-red-300">{error}</p>}<Button className="w-full" type="submit" disabled={password.length < 8}>{configured ? "Sign in" : "Create admin account"}</Button></form></Card></main>;
}

type NavigationItem = readonly [Tab, typeof Activity, string, ownerOnly?: boolean];
const navigation: ReadonlyArray<NavigationItem> = [["overview", Activity, "Overview"], ["settings", Settings2, "Settings"], ["versions", Download, "Versions"], ["mods", Boxes, "Mods"], ["saves", Save, "Saves"], ["players", Users, "Players"], ["logs", TerminalSquare, "Logs"], ["health", HeartPulse, "System Health"], ["users", Users, "Accounts", true], ["audit", Activity, "Audit log", true]];
let currentRole: Me["role"];
const stateClasses: Record<State, string> = { running: "bg-emerald-500/20 text-emerald-300", stopped: "bg-zinc-700 text-zinc-200", starting: "bg-yellow-500/20 text-yellow-300", stopping: "bg-yellow-500/20 text-yellow-300", failed: "bg-red-500/20 text-red-300" };

export function App() {
  const [configured, setConfigured] = useState<boolean>(); const [signedIn, setSignedIn] = useState(false); const [me, setMe] = useState<Me>(); const [tab, setTab] = useState<Tab>("overview"); const [status, setStatus] = useState<Status>(); const [settings, setSettings] = useState<Settings>(); const [logs, setLogs] = useState<string[]>([]); const [error, setError] = useState("");
  const handleUnauthorized = useCallback(() => { csrf = ""; setMe(undefined); setSignedIn(false); setError("Your session expired. Please sign in again."); }, []);
  useEffect(() => { onUnauthorized = handleUnauthorized; return () => { onUnauthorized = undefined; }; }, [handleUnauthorized]);
  const refresh = useCallback(async () => { try { const [nextStatus, nextSettings, nextLogs] = await Promise.all([api<Status>("/api/status"), api<Settings>("/api/settings"), api<string[]>("/api/logs")]); setStatus(nextStatus); setSettings(nextSettings); setLogs(nextLogs); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not load server state."); } }, []);
  useEffect(() => { api<{ configured: boolean }>("/api/auth/status").then(result => { setConfigured(result.configured); if (result.configured) api<Me>("/api/auth/me").then(current => { csrf = current.csrfToken; setMe(current); setSignedIn(true); }).catch(() => undefined); }).catch(() => setConfigured(false)); }, []);
  useEffect(() => { if (!signedIn) return; void refresh(); const connection = new HubConnectionBuilder().withUrl("/hubs/status").withAutomaticReconnect().build(); connection.on("status", setStatus); connection.on("log", (line: string) => setLogs(current => [...current.slice(-499), `${new Date().toISOString()} ${line}`])); void connection.start(); return () => { void connection.stop(); }; }, [signedIn, refresh]);
  const action: Action = async (path, init = { method: "POST" }) => { try { setError(""); await api(path, init); await refresh(); return true; } catch (caught) { setError(caught instanceof Error ? caught.message : "Request failed."); return false; } };
  async function finishSignIn() { try { const current = await api<Me>("/api/auth/me"); setMe(current); setSignedIn(true); } catch (caught) { setError(caught instanceof Error ? caught.message : "Authentication failed."); } }
  if (configured === undefined) return <main className="p-8 text-zinc-400">Loading…</main>;
  if (!signedIn) return <Auth configured={configured} done={() => void finishSignIn()} />;
  const visibleNavigation = navigation.filter(([, , , ownerOnly]) => !ownerOnly || me?.role === "owner");
  const title = navigation.find(item => item[0] === tab)?.[2];
  return <div className="min-h-screen md:grid md:grid-cols-[15rem_1fr]"><aside className="border-b border-zinc-800 bg-zinc-900/50 p-4 md:min-h-screen md:border-b-0 md:border-r"><div className="mb-7 flex items-center gap-2 font-bold"><Gamepad2 className="text-yellow-400" />Factorio Manager</div><nav className="flex gap-2 overflow-x-auto md:flex-col">{visibleNavigation.map(([id, Icon, label]) => <button key={id} onClick={() => setTab(id)} className={`flex items-center gap-3 rounded-md px-3 py-2 text-sm ${tab === id ? "bg-yellow-400 text-zinc-950" : "text-zinc-300 hover:bg-zinc-800"}`}><Icon size={17} />{label}</button>)}</nav><Button variant="outline" className="mt-8 w-full" onClick={() => void api("/api/auth/logout", { method: "POST" }).catch(() => undefined).finally(() => { csrf = ""; setMe(undefined); setSignedIn(false); })}><LogOut size={16} className="mr-2" />Sign out</Button></aside><main className="mx-auto w-full max-w-6xl p-5 md:p-8"><header className="mb-7 flex items-center justify-between"><div><h1 className="text-2xl font-bold">{title}</h1><p className="text-sm text-zinc-400">One container, one Factorio server · {me?.name} ({me?.role})</p></div>{status && <span className={`rounded-full px-3 py-1 text-xs font-semibold uppercase ${stateClasses[status.state]}`}>{status.state}</span>}</header>{error && <p className="mb-5 rounded bg-red-950 p-3 text-sm text-red-300">{error}</p>}{tab === "users" && me?.role === "owner" ? <Accounts /> : tab === "audit" && me?.role === "owner" ? <AuditLog /> : tab === "overview" ? <Overview status={status} settings={settings} action={action} role={me?.role} /> : tab === "settings" && settings ? <SettingsPage settings={settings} action={action} canEdit={(me?.role === "owner" || me?.role === "admin") && status?.state === "stopped"} canManage={me?.role === "owner" || me?.role === "admin"} /> : tab === "versions" ? <Versions settings={settings} action={action} role={me?.role} /> : tab === "mods" ? <Mods action={action} role={me?.role} status={status} /> : tab === "saves" ? <Saves action={action} role={me?.role} status={status} /> : tab === "players" ? <Players action={action} role={me?.role} /> : tab === "logs" ? <Logs logs={logs} /> : tab === "health" ? <Health /> : <Card><p className="text-sm text-zinc-400">Owner permissions are required to view this page.</p></Card>}</main></div>;
}

function Accounts() {
  const [users, setUsers] = useState<User[]>([]); const [username, setUsername] = useState(""); const [password, setPassword] = useState(""); const [role, setRole] = useState<"admin"|"viewer">("viewer"); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const load = useCallback(async () => { setLoading(true); try { setUsers(await api<User[]>("/api/users")); setError(""); } catch (e) { setError(e instanceof Error ? e.message : "Forbidden"); } finally { setLoading(false); } }, []); useEffect(() => { void load(); }, [load]);
  async function create() { if (password.length < 8) { setError("Password must be at least 8 characters."); return; } try { await api("/api/users", { method: "POST", body: JSON.stringify({ username, password, role }) }); setUsername(""); setPassword(""); load(); } catch (e) { setError(e instanceof Error ? e.message : "Could not create account."); } }
  async function changeRole(u: User, next: string) { if (!window.confirm(`Change ${u.username}'s role?`)) return; try { await api(`/api/users/${u.id}/role`, { method: "PATCH", body: JSON.stringify({ role: next }) }); load(); } catch (e) { setError(e instanceof Error ? e.message : "Role change failed."); } }
  async function resetPassword(u: User) { const next = window.prompt("New password (at least 8 characters)"); if (!next || next.length < 8 || !window.confirm(`Reset ${u.username}'s password?`)) return; try { await api(`/api/users/${u.id}/password`, { method: "POST", body: JSON.stringify({ password: next }) }); setError("Password reset successfully."); } catch (e) { setError(e instanceof Error ? e.message : "Password reset failed."); } }
  return <div className="space-y-5"><Card className="space-y-3"><h2 className="font-semibold">Accounts</h2><div className="grid gap-2 md:grid-cols-4"><input placeholder="Username" value={username} onChange={e=>setUsername(e.target.value)} /><input type="password" placeholder="Temporary password (8+ characters)" value={password} onChange={e=>setPassword(e.target.value)} /><select value={role} onChange={e=>setRole(e.target.value as typeof role)}><option value="viewer">Viewer</option><option value="admin">Admin</option></select><Button onClick={()=>void create()} disabled={!username || password.length<8}>Create</Button></div>{error&&<p className="text-sm text-red-300">{error}</p>}</Card><Card><div className="space-y-2">{loading ? <p className="text-sm text-zinc-400">Loading accounts…</p> : users.length ? users.map(u=><div key={u.id} className="flex flex-wrap items-center justify-between gap-2 rounded border border-zinc-800 p-3 text-sm"><span>{u.username} <span className="text-zinc-500">({u.role})</span></span>{u.role!=="owner"&&<div className="flex gap-2"><select value={u.role} onChange={e=>void changeRole(u,e.target.value)}><option value="viewer">Viewer</option><option value="admin">Admin</option></select><Button size="sm" variant="outline" onClick={()=>void resetPassword(u)}>Reset password</Button><Button size="sm" variant="destructive" onClick={()=>{if(window.confirm(`Delete ${u.username}?`)) void api(`/api/users/${u.id}`,{method:"DELETE"}).then(load)}}><Trash2 size={15}/></Button></div>}</div>) : <p className="text-sm text-zinc-400">No accounts found.</p>}</div></Card></div>;
}

function AuditLog() { const [events,setEvents]=useState<AuditEvent[]>([]); const [before,setBefore]=useState<number>(); const [loading,setLoading]=useState(true); const [error,setError]=useState(""); const load=useCallback(async()=>{setLoading(true); try { const q=before?`?beforeId=${before}&limit=50`:"?limit=50"; setEvents(await api<AuditEvent[]>(`/api/audit-events${q}`)); setError(""); } catch(e) { setError(e instanceof Error ? e.message : "Could not load audit log."); } finally { setLoading(false); }},[before]); useEffect(()=>{void load();},[load]); return <Card><h2 className="mb-3 font-semibold">Audit log</h2>{error&&<p className="mb-3 text-sm text-red-300">{error}</p>}{loading ? <p className="text-sm text-zinc-400">Loading audit events…</p> : <div className="space-y-2">{events.length ? events.map(e=><div key={e.id} className="flex justify-between rounded border border-zinc-800 p-3 text-sm"><span>{new Date(e.occurredAtUtc).toLocaleString()} · {e.action}</span><span className={e.outcome==="success"?"text-emerald-300":e.outcome==="denied"?"text-amber-300":"text-red-300"}>{e.outcome}</span></div>) : <p className="text-sm text-zinc-400">No audit events found.</p>}</div>}<Button className="mt-4" variant="outline" disabled={loading || !events.length} onClick={()=>setBefore(events.at(-1)?.id)}>Older</Button></Card>; }

function Logs({ logs }: { logs: string[] }) {
  const [query, setQuery] = useState("");
  const filtered = query.trim() ? logs.filter(line => line.toLowerCase().includes(query.toLowerCase())) : logs;
  return <Card><div className="mb-3 flex flex-wrap gap-2"><label className="flex min-w-0 flex-1 items-center gap-2"><Search size={16} className="text-zinc-500" /><input placeholder="Filter logs" value={query} onChange={event => setQuery(event.target.value)} /></label><Button variant="outline" onClick={() => { window.location.href = "/api/logs/download"; }}><Download className="mr-2" size={16} />Download</Button></div><p className="mb-2 text-xs text-zinc-500">Showing {filtered.length} of {logs.length} in-memory lines. The server rotates the file at 10 MB.</p><pre className="max-h-[65vh] overflow-auto whitespace-pre-wrap break-words font-mono text-xs text-zinc-300">{filtered.join("\n") || "No matching server output."}</pre></Card>;
}

function Health() {
  const [health, setHealth] = useState<SystemHealth>();
  const [maintenance, setMaintenance] = useState<MaintenanceStatus>();
  const [error, setError] = useState("");
  const load = useCallback(async () => { try { const [nextHealth, nextMaintenance] = await Promise.all([api<SystemHealth>("/api/system-health"), api<MaintenanceStatus>("/api/maintenance")]); setHealth(nextHealth); setMaintenance(nextMaintenance); setError(""); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not load system health."); } }, []);
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(), 15000); return () => window.clearInterval(timer); }, [load]);
  const bytes = (value?: number) => value === undefined ? "—" : `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`;
  const uptime = (seconds = 0) => `${Math.floor(seconds / 86400)}d ${Math.floor(seconds / 3600) % 24}h ${Math.floor(seconds / 60) % 60}m`;
  if (error) return <Card><p className="text-sm text-red-300">{error}</p></Card>;
  if (!health || !maintenance) return <Card><p className="text-sm text-zinc-400">Loading system health…</p></Card>;
  const date = (value?: string) => value ? new Date(value).toLocaleString() : "ยังไม่มีข้อมูล";
  return <div className="grid gap-5 md:grid-cols-2"><Card><h2 className="mb-4 font-semibold">Runtime health</h2><dl className="space-y-3 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Uptime</dt><dd>{uptime(health.uptimeSeconds)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Working set</dt><dd>{bytes(health.workingSetBytes)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Database</dt><dd className="text-emerald-300">{health.databasePresent ? "Available" : "Missing"}</dd></div></dl></Card><Card><h2 className="mb-4 font-semibold">Data inventory</h2><dl className="space-y-3 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Disk free</dt><dd>{bytes(health.dataFreeBytes)} / {bytes(health.dataTotalBytes)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Saves</dt><dd>{health.saveCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Backups</dt><dd>{health.backupCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Cached versions</dt><dd>{health.versionCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Mod archives</dt><dd>{health.modFileCount}</dd></div></dl></Card><Card className="md:col-span-2"><h2 className="mb-4 font-semibold">Scheduled maintenance</h2><dl className="grid gap-3 text-sm md:grid-cols-2"><div><dt className="text-zinc-400">Backup schedule</dt><dd>ทุก {maintenance.backupIntervalHours} ชั่วโมง · เก็บ {maintenance.backupRetention} ชุด</dd></div><div><dt className="text-zinc-400">Last backup</dt><dd>{date(maintenance.lastScheduledBackup)}</dd></div><div><dt className="text-zinc-400">Next backup</dt><dd>{date(maintenance.nextScheduledBackup)}</dd></div><div><dt className="text-zinc-400">Last update check</dt><dd>{date(maintenance.lastUpdateCheck)}</dd></div><div><dt className="text-zinc-400">Next update check</dt><dd>{date(maintenance.nextUpdateCheck)}</dd></div></dl><p className="mt-4 text-xs text-zinc-500">Updated {new Date(health.checkedAt).toLocaleString()}</p></Card></div>;
}

function Overview({ status, settings, action, role }: { status?: Status; settings?: Settings; action: Action; role?: Me["role"] }) { const canControl = role === "owner" || role === "admin"; return <div className="grid gap-5 lg:grid-cols-3"><Card className="lg:col-span-2"><h2 className="mb-1 text-lg font-semibold">{settings?.serverName ?? "Server"}</h2><p className="mb-5 text-sm text-zinc-400">{settings?.description}</p><div className="flex flex-wrap gap-3"><Button onClick={() => void action("/api/control/start")} disabled={!canControl || status?.state === "running" || status?.state === "starting"}><CirclePlay className="mr-2" size={17} />Start</Button><Button variant="destructive" onClick={() => void action("/api/control/stop")} disabled={!canControl || status?.state !== "running"}><CircleStop className="mr-2" size={17} />Stop</Button><Button variant="secondary" onClick={() => void action("/api/control/restart")} disabled={!canControl || status?.state !== "running"}>Restart</Button></div>{!canControl && <p className="mt-3 text-xs text-zinc-500">Server control requires owner or admin access.</p>}{status?.message && <p className="mt-4 text-sm text-red-300">{status.message}</p>}</Card><Card><h2 className="mb-3 font-semibold">Runtime</h2><dl className="space-y-2 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Version</dt><dd>{settings?.activeVersion ?? "Not selected"}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Save</dt><dd>{settings?.activeSave ?? "Not selected"}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Process</dt><dd>{status?.processId ?? "—"}</dd></div></dl></Card></div>; }

function SettingsPage({ settings, action, canEdit, canManage }: { settings: Settings; action: Action; canEdit: boolean; canManage: boolean }) {
  const [draft, setDraft] = useState(settings);
  const map = draft.mapGeneration ?? {} as MapGeneration;
  const setMap = (key: keyof MapGeneration, value: unknown) => setDraft({ ...draft, mapGeneration: { ...map, [key]: value } });
  const number = (key: keyof MapGeneration) => ({ type: "number" as const, value: String(map[key] ?? ""), onChange: (event: ChangeEvent<HTMLInputElement>) => setMap(key, Number(event.target.value)) });
  const select = (key: keyof MapGeneration) => ({ value: String(map[key] ?? "normal"), onChange: (event: ChangeEvent<HTMLSelectElement>) => setMap(key, event.target.value) });
  const levels = ["very-low", "low", "normal", "high", "very-high", "none"];
  const resource = (key: keyof MapGeneration, label: string, description: string, includeRichness = true) => { const value = (map[key] ?? {}) as ResourceSettings; const update = (part: keyof ResourceSettings, next: string) => setMap(key, { ...value, [part]: next }); const parts = includeRichness ? (["frequency", "size", "richness"] as const) : (["frequency", "size"] as const); return <div className="rounded border border-zinc-800 p-3"><p className="font-medium">{label}</p><p className="mb-2 text-xs text-zinc-400">{description}</p><div className="grid grid-cols-3 gap-2">{parts.map(part => <label key={part} className="text-xs capitalize">{part === "frequency" ? "ความถี่" : part === "size" ? "ขนาด" : "ความอุดมสมบูรณ์"}<select value={value[part] ?? "normal"} onChange={event => update(part, event.target.value)}>{levels.map(level => <option key={level}>{level}</option>)}</select></label>)}</div></div>; };
  return <form onSubmit={event => { event.preventDefault(); void action("/api/settings", { method: "PUT", body: JSON.stringify(draft) }); }} className="grid gap-5 lg:grid-cols-2">
    <Card className="space-y-3"><h2 className="font-semibold">Server</h2><label className="block text-sm">Server name<input value={draft.serverName} onChange={event => setDraft({ ...draft, serverName: event.target.value })} /></label><label className="block text-sm">Description<input value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></label><label className="block text-sm">Max players (0 = unlimited)<input type="number" value={draft.maxPlayers} onChange={event => setDraft({ ...draft, maxPlayers: Number(event.target.value) })} /></label><label className="block text-sm">Autosave minutes<input type="number" value={draft.autosaveMinutes} onChange={event => setDraft({ ...draft, autosaveMinutes: Number(event.target.value) })} /></label></Card>
    <Card className="space-y-3"><h2 className="font-semibold">Maintenance</h2><label className="block text-sm">Backup interval (hours)<input type="number" value={draft.backupIntervalHours} onChange={event => setDraft({ ...draft, backupIntervalHours: Number(event.target.value) })} /></label><label className="block text-sm">Backup retention<input type="number" value={draft.backupRetention} onChange={event => setDraft({ ...draft, backupRetention: Number(event.target.value) })} /></label><label className="block text-sm">Timezone<input value={draft.timeZone} onChange={event => setDraft({ ...draft, timeZone: event.target.value })} /></label><label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={draft.visibilityPublic} onChange={event => setDraft({ ...draft, visibilityPublic: event.target.checked })} />List publicly</label></Card>
    <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">สร้างแผนที่ — Map settings</h2><p className="text-sm text-zinc-400">ค่าด้านล่างตรงกับหน้า New Game ของ Factorio และจะถูกใช้เมื่อกด Create map เท่านั้น การเปลี่ยนค่าจะไม่แก้แผนที่เดิม</p><div className="grid gap-3 md:grid-cols-3"><label className="text-sm">Seed (ว่าง = สุ่ม)<input type="number" value={map.seed ?? ""} onChange={event => setMap("seed", event.target.value ? Number(event.target.value) : undefined)} /></label><label className="text-sm">ความกว้างแผนที่ (tiles)<input type="number" min="0" value={map.width} onChange={event => setMap("width", Number(event.target.value))} /><span className="text-xs text-zinc-500">0 = ไม่จำกัด; ค่าที่กำหนดต้องไม่น้อยกว่า 64</span></label><label className="text-sm">ความสูงแผนที่ (tiles)<input type="number" min="0" value={map.height} onChange={event => setMap("height", Number(event.target.value))} /><span className="text-xs text-zinc-500">0 = ไม่จำกัด; ใช้จำกัดขนาดโลกสำหรับเซิร์ฟเวอร์ที่ต้องการประหยัดพื้นที่</span></label><label className="text-sm">น้ำ — Water<select {...select("water")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ความถี่และขนาดของทะเลสาบ/แม่น้ำ</span></label><label className="text-sm">พื้นที่เริ่มต้น<select {...select("startingArea")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">พื้นที่ปลอดภัยรอบจุดเริ่มต้น</span></label><label className="text-sm">ความหลากหลายภูมิประเทศ<select {...select("terrainSegmentation")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ขนาดของพื้นที่ทุ่ง/ป่า/ภูเขา</span></label><label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={map.peacefulMode} onChange={event => setMap("peacefulMode", event.target.checked)} />Peaceful mode — ศัตรูไม่โจมตีก่อน</label></div></Card>
    <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">ทรัพยากร — Resources</h2><p className="text-xs text-zinc-400">ความถี่ = จำนวนแหล่ง, ขนาด = พื้นที่แหล่ง, ความอุดมสมบูรณ์ = ปริมาณต่อแหล่ง ระดับ none ปิดทรัพยากรนั้น</p><div className="grid gap-3 md:grid-cols-2">{resource("ironOre", "Iron ore", "แร่เหล็กสำหรับแผ่นเหล็กและเครื่องจักร")} {resource("copperOre", "Copper ore", "แร่ทองแดงสำหรับวงจรและสายไฟ")} {resource("stone", "Stone", "หินสำหรับเตาและสิ่งก่อสร้าง")} {resource("coal", "Coal", "ถ่านหินสำหรับเชื้อเพลิงและพลาสติก")} {resource("uraniumOre", "Uranium ore", "แร่ยูเรเนียมสำหรับพลังงานนิวเคลียร์")} {resource("crudeOil", "Crude oil", "บ่อน้ำมันสำหรับผลิตภัณฑ์ปิโตรเลียม")} {resource("trees", "Trees", "ความถี่และขนาดของกลุ่มต้นไม้ในแผนที่", false)}</div></Card>
    <Card className="space-y-3"><h2 className="font-semibold">ศัตรูและการขยายฐาน</h2>{resource("enemyBase", "Enemy bases", "ความถี่ ขนาด และความแข็งแกร่งของฐานศัตรูที่สร้างบนแผนที่")}<label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={map.enemyExpansionEnabled} onChange={event => setMap("enemyExpansionEnabled", event.target.checked)} />เปิดการขยายฐานศัตรู</label><label className="text-sm">ระยะผู้เล่นขั้นต่ำ<input {...number("enemyExpansionMinDistance")} /><span className="text-xs text-zinc-500">ระยะห่างขั้นต่ำจากผู้เล่น (หน่วย chunk) ที่กลุ่มขยายฐานจะเริ่มตั้งฐานใหม่</span></label><label className="text-sm">ระยะขยายสูงสุด<input {...number("enemyExpansionMaxDistance")} /><span className="text-xs text-zinc-500">ระยะไกลสุดจากฐานเดิมที่อนุญาตให้เลือกตำแหน่งฐานใหม่ ยิ่งสูงยิ่งกระจายไกล</span></label><label className="text-sm">ขนาดกลุ่มผู้ตั้งถิ่นฐานขั้นต่ำ<input {...number("settlerGroupMinSize")} /><span className="text-xs text-zinc-500">จำนวนยูนิตขั้นต่ำในกลุ่มที่เดินทางไปสร้างฐานใหม่</span></label><label className="text-sm">ขนาดกลุ่มผู้ตั้งถิ่นฐานสูงสุด<input {...number("settlerGroupMaxSize")} /><span className="text-xs text-zinc-500">จำนวนยูนิตสูงสุดในกลุ่มขยายฐาน ยิ่งมากยิ่งป้องกันกลุ่มได้ดี</span></label><label className="text-sm">คูลดาวน์ขยายฐานขั้นต่ำ (นาที)<input {...number("expansionMinCooldown")} /><span className="text-xs text-zinc-500">เวลาขั้นต่ำระหว่างการพยายามขยายฐานแต่ละครั้ง ระบบจะแปลงเป็น ticks ให้ Factorio</span></label><label className="text-sm">คูลดาวน์ขยายฐานสูงสุด (นาที)<input {...number("expansionMaxCooldown")} /><span className="text-xs text-zinc-500">เวลาสูงสุดที่สุ่มรอก่อนการขยายครั้งถัดไป ต้องไม่น้อยกว่าค่าขั้นต่ำ</span></label></Card>
    <Card className="space-y-3"><h2 className="font-semibold">วิวัฒนาการและหน้าผา</h2><p className="text-xs text-zinc-400">เปอร์เซ็นต์คือสัดส่วนผลกระทบต่อ evolution factor: เวลา มลพิษ และการทำลายฐานศัตรู ยิ่งสูงศัตรูยิ่งแข็งเร็ว</p><label className="text-sm">Evolution จากเวลา (%)<input {...number("evolutionTime")} /></label><label className="text-sm">Evolution จากมลพิษ (%)<input {...number("evolutionPollution")} /></label><label className="text-sm">Evolution จากการทำลายฐาน (%)<input {...number("evolutionDestroy")} /></label><label className="text-sm">ระยะระดับหน้าผา<input {...number("cliffElevationInterval")} /><span className="text-xs text-zinc-500">ความสูงภูมิประเทศที่ต้องเปลี่ยนก่อนสร้างชั้นหน้าผา ค่าสูงทำให้หน้าผาห่างกัน</span></label><label className="text-sm">Offset ระดับหน้าผา<input {...number("cliffElevationOffset")} /><span className="text-xs text-zinc-500">เลื่อนระดับความสูงอ้างอิงของหน้าผา ใช้ปรับจังหวะการเกิดหน้าผาบนแผนที่</span></label><label className="text-sm">ความอุดมสมบูรณ์ของหน้าผา<select {...select("cliffRichness")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ระดับความหนาแน่น/ความถี่ของแนวหน้าผา none คือปิดหน้าผา</span></label></Card>
    <div className="lg:col-span-2"><Button type="submit" disabled={!canEdit}><Settings2 className="mr-2" size={16} />Save settings</Button>{!canEdit && <p className="mt-2 text-xs text-zinc-500">Settings changes require owner/admin access and a stopped server.</p>}</div>
    <PasswordCard action={action} />
    <FactorioCredentialsCard action={action} canEdit={canEdit || canManage} />
  </form>;
}

function FactorioCredentialsCard({ action, canEdit }: { action: Action; canEdit: boolean }) {
  const [username, setUsername] = useState(""); const [token, setToken] = useState(""); const [configured, setConfigured] = useState<boolean>(); const [message, setMessage] = useState("");
  useEffect(() => { void api<{ configured: boolean }>("/api/factorio-credentials/status").then(result => setConfigured(result.configured)).catch(() => setConfigured(false)); }, []);
  async function save() { setMessage(""); if (!username.trim() || !token.trim()) { setMessage("Enter both the Factorio username and token."); return; } if (await action("/api/factorio-credentials", { method: "PUT", body: JSON.stringify({ username, token }) })) { setToken(""); setConfigured(true); setMessage("Factorio credentials saved. Mod Portal search and downloads can try again."); } }
  return <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">Factorio account for Mod Portal</h2><p className="text-xs text-zinc-400">ใช้สำหรับค้นหาและดาวน์โหลด mod จาก Mod Portal เท่านั้น ระบบจะเก็บ token ไว้ในไฟล์ secret และจะไม่แสดงกลับมา {!configured ? "ยังไม่ได้ตั้งค่า credential" : "มี credential ตั้งค่าอยู่แล้ว หาก Mod Portal แจ้งว่าไม่ถูกต้อง ให้กรอกใหม่"}</p><div className="grid gap-3 md:grid-cols-2"><input disabled={!canEdit} placeholder="Factorio username" value={username} onChange={event => setUsername(event.target.value)} /><input disabled={!canEdit} type="password" placeholder="Factorio token" value={token} onChange={event => setToken(event.target.value)} /></div><div className="flex items-center gap-3"><Button type="button" disabled={!canEdit || !username.trim() || !token.trim()} onClick={() => void save()}>Save Factorio credentials</Button>{!canEdit && <span className="text-xs text-zinc-500">ต้องเป็น owner/admin และหยุดเซิร์ฟเวอร์ก่อนแก้ไข</span>}{message && <span className="text-sm text-zinc-300">{message}</span>}</div></Card>;
}

function PasswordCard({ action }: { action: Action }) {
  const [currentPassword, setCurrentPassword] = useState(""); const [newPassword, setNewPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [message, setMessage] = useState("");
  async function submit() { setMessage(""); if (newPassword.length < 8) { setMessage("New password must be at least 8 characters."); return; } if (newPassword !== confirmation) { setMessage("New passwords do not match."); return; } if (await action("/api/auth/password", { method: "POST", body: JSON.stringify({ currentPassword, newPassword }) })) { setCurrentPassword(""); setNewPassword(""); setConfirmation(""); setMessage("Password changed."); } }
  return <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">Change admin password</h2><p className="text-xs text-zinc-400">ใช้รหัสผ่านใหม่อย่างน้อย 8 ตัวอักษร การเปลี่ยนรหัสผ่านจะไม่ทำให้ session ปัจจุบันหลุดออก</p><div className="grid gap-3 md:grid-cols-3"><input type="password" placeholder="Current password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} /><input type="password" minLength={8} placeholder="New password" value={newPassword} onChange={event => setNewPassword(event.target.value)} /><input type="password" minLength={8} placeholder="Confirm new password" value={confirmation} onChange={event => setConfirmation(event.target.value)} /><div className="md:col-span-3 flex items-center gap-3"><Button type="button" onClick={() => void submit()}>Change password</Button>{message && <span className="text-sm text-zinc-400">{message}</span>}</div></div></Card>;
}

function Versions({ settings, action, role }: { settings?: Settings; action: Action; role?: Me["role"] }) {
  const [version, setVersion] = useState(settings?.activeVersion ?? "");
  const [channel, setChannel] = useState<"stable" | "experimental">(settings?.channel ?? "stable");
  const [cached, setCached] = useState<string[]>([]); const [catalog, setCatalog] = useState<VersionCatalog>(); const [update, setUpdate] = useState<UpdateStatus>();
  const [checking, setChecking] = useState(false); const [loading, setLoading] = useState(true); const [downloading, setDownloading] = useState(false); const [applying, setApplying] = useState(false); const [message, setMessage] = useState("");
  const canMutate = role === "owner" || role === "admin";
  useEffect(() => { if (settings?.activeVersion) setVersion(current => current || settings.activeVersion!); if (settings?.channel) setChannel(settings.channel); }, [settings?.activeVersion, settings?.channel]);
  const load = useCallback(async () => { setLoading(true); try { const [nextCached, nextUpdate, nextCatalog] = await Promise.all([api<string[]>("/api/versions"), api<UpdateStatus | null>("/api/updates"), api<VersionCatalog>("/api/versions/catalog")]); setCached(nextCached ?? []); setUpdate(nextUpdate ?? undefined); setCatalog(nextCatalog ?? {}); setMessage(""); } catch (e) { setMessage(e instanceof Error ? e.message : "Could not load version catalog."); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function checkForUpdates() { setChecking(true); try { setUpdate(await api<UpdateStatus>("/api/updates/check", { method: "POST" })); } catch (e) { setMessage(e instanceof Error ? e.message : "Update check failed."); } finally { setChecking(false); } }
  async function download() { if (!version || !canMutate || downloading) return; setDownloading(true); setMessage(""); try { if (await action(`/api/versions/download/${channel}/${encodeURIComponent(version)}`)) { setMessage(`Factorio ${version} downloaded successfully.`); await load(); } } finally { setDownloading(false); } }
  async function apply() { if (!version || !canMutate || applying || !window.confirm(`Apply Factorio ${version}? The active save will be backed up first and the server may restart.`)) return; setApplying(true); setMessage(""); try { if (await action("/api/versions/apply", { method: "POST", body: JSON.stringify({ version, channel }) })) { setMessage(`Factorio ${version} is now selected.`); await load(); } } finally { setApplying(false); } }
  const checkedAt = update?.checkedAt ? new Date(update.checkedAt).toLocaleString() : "never"; const recommended = catalog?.[channel]?.headless; const choices = Array.from(new Set([recommended, ...cached].filter((item): item is string => Boolean(item))));
  return <div className="grid gap-5 lg:grid-cols-2"><Card className="space-y-3"><div className="flex items-center justify-between"><h2 className="font-semibold">Version</h2><Button size="sm" variant="outline" onClick={() => void checkForUpdates()} disabled={checking || !settings?.activeVersion}>{checking ? "Checking…" : "Check for updates"}</Button></div>{message && <p className="rounded bg-amber-950 p-3 text-sm text-amber-200">{message}</p>}{update?.availableVersion ? <div className="rounded border border-yellow-500/50 bg-yellow-500/10 p-3 text-sm text-yellow-200"><p className="font-semibold">Update available: {update.availableVersion}</p><p className="mt-1 text-yellow-100/70">Automatic updates are disabled. A recovery backup is created before Apply.</p></div> : !message && <p className="text-xs text-zinc-500">Last checked: {checkedAt}</p>}{loading ? <p className="text-sm text-zinc-400">Loading version catalog…</p> : <><label className="block text-sm">Channel<select value={channel} onChange={event => setChannel(event.target.value as typeof channel)}><option value="stable">Stable {catalog?.stable?.headless ? `(${catalog.stable.headless})` : ""}</option><option value="experimental">Experimental {catalog?.experimental?.headless ? `(${catalog.experimental.headless})` : ""}</option></select></label><label className="block text-sm">Choose cached/catalog version<select value={choices.includes(version) ? version : ""} onChange={event => setVersion(event.target.value)}><option value="">Select a version…</option>{choices.map(item => <option key={item} value={item}>{item}{cached.includes(item) ? " · cached" : ""}</option>)}</select></label><label className="block text-sm">Custom version<input placeholder="e.g. 2.0.77" value={version} onChange={event => setVersion(event.target.value.trim())} /></label><div className="flex flex-wrap gap-2"><Button onClick={() => void download()} disabled={!version || !canMutate || downloading}>{downloading ? "Downloading…" : "Download"}</Button><Button variant="secondary" onClick={() => void apply()} disabled={!version || !canMutate || applying || !cached.includes(version)}>{applying ? "Applying…" : "Apply selected version"}</Button></div>{!canMutate && <p className="text-xs text-zinc-500">Version download/apply requires owner or admin access.</p>}</>}</Card><Card><h2 className="mb-3 font-semibold">Cached versions</h2><div className="space-y-2">{cached.length ? cached.map(item => <button key={item} className={`block w-full rounded border px-3 py-2 text-left text-sm ${item === version ? "border-yellow-400" : "border-zinc-700"}`} onClick={() => setVersion(item)}>{item}{item === settings?.activeVersion && <span className="ml-2 text-xs text-emerald-300">active</span>}</button>) : <p className="text-sm text-zinc-400">No server versions downloaded.</p>}</div></Card></div>;
}

function Mods({ action, role, status }: { action: Action; role?: Me["role"]; status?: Status }) {
  const [selectedResults, setSelectedResults] = useState<string[]>([]); const [portalFilter, setPortalFilter] = useState(""); const [portalSort, setPortalSort] = useState<"name" | "version">("name"); const [portalPage, setPortalPage] = useState(1);
  const [query, setQuery] = useState(""); const [results, setResults] = useState<PortalMod[]>([]); const [installed, setInstalled] = useState<Mod[]>([]); const [updates, setUpdates] = useState<ModUpdateInfo[]>([]); const [profiles, setProfiles] = useState<ModProfile[]>([]); const [profileName, setProfileName] = useState(""); const [file, setFile] = useState<File>(); const [filter, setFilter] = useState("all"); const [installedQuery, setInstalledQuery] = useState(""); const [installedSort, setInstalledSort] = useState<"name" | "version">("name"); const [installedPage, setInstalledPage] = useState(1); const [checking, setChecking] = useState(false); const [searching, setSearching] = useState(false); const [installing, setInstalling] = useState(""); const [message, setMessage] = useState(""); const [searchError, setSearchError] = useState(""); const [recovery, setRecovery] = useState<ModRecovery>(); const [preview, setPreview] = useState<ModPreflight>();
  const canMutate = (role === "owner" || role === "admin") && status?.state === "stopped";
  const load = useCallback(async () => { try { const [mods, ps, pending] = await Promise.all([api<Mod[]>("/api/mods"), api<ModProfile[]>("/api/mods/profiles"), api<ModRecovery>("/api/mods/recovery")]); setInstalled(mods); setProfiles(ps); setRecovery(pending); } catch (e) { setMessage(e instanceof Error ? e.message : "Could not load mods."); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function search(event: FormEvent) { event.preventDefault(); if (!query.trim() || searching) return; setSearching(true); setSearchError(""); try { const response = await api<PortalSearchResponse>(`/api/mods/search?query=${encodeURIComponent(query.trim())}`); setResults(response.results ?? []); setSelectedResults([]); setPortalPage(1); } catch (e) { setSearchError(e instanceof Error ? e.message : "Mod search failed."); setResults([]); } finally { setSearching(false); } }
  async function installSelected() { const names = selectedResults; if (!canMutate || installing || !names.length) return; if (!window.confirm(`Install ${names.length} selected mod(s) with dependencies?`)) return; setInstalling("selected"); try { for (const name of names) { const check = await preflight("install", [name]); if (check?.blockers.length) { setMessage(`Install blocked for ${name}: ${check.blockers.join(", ")}`); return; } const succeeded = await mutate("/api/mods/install", { method: "POST", body: JSON.stringify({ name, enabled: true, includeDependencies: true, confirm: true }) }, `${name} installed.`); if (!succeeded) return; } setSelectedResults([]); setMessage(`${names.length} selected mod(s) installed.`); } finally { setInstalling(""); } }
  async function checkUpdates() { setChecking(true); try { setUpdates(await api<ModUpdateInfo[]>("/api/mods/updates")); } catch (e) { setMessage(e instanceof Error ? e.message : "Update check failed."); } finally { setChecking(false); } }
  async function preflight(operation: string, names: string[] = []) { try { const result = await api<ModPreflight>("/api/mods/preflight", { method: "POST", body: JSON.stringify({ operation, names }) }); setPreview(result); return result; } catch (e) { setMessage(e instanceof Error ? e.message : "Preflight failed."); return undefined; } }
  async function mutate(path: string, init: RequestInit, success: string): Promise<boolean> { if (!canMutate) return false; const succeeded = await action(path, init); if (succeeded) { setMessage(success); setPreview(undefined); await load(); } return succeeded; }
  async function install(name: string) { if (installing) return; setInstalling(name); try { const check = await preflight("install", [name]); if (!canMutate || check?.blockers.length || !window.confirm(`${name} and required dependencies will be installed. Continue?`)) return; await mutate("/api/mods/install", { method: "POST", body: JSON.stringify({ name, enabled: true, includeDependencies: true, confirm: true }) }, `${name} installed.`); } finally { setInstalling(""); } }
  async function upload() { if (!file || !canMutate) return; const check = await preflight("upload", [file.name]); if (check?.blockers.length || !window.confirm(`Upload ${file.name} and resolve required dependencies?`)) return; const form = new FormData(); form.append("file", file); form.append("enabled", "true"); form.append("includeDependencies", "true"); if (await mutate("/api/mods/upload", { method: "POST", body: form }, `${file.name} uploaded.`)) setFile(undefined); }
  async function uninstall(mod: Mod) { if (!canMutate || !window.confirm(`Uninstall ${mod.name}?`)) return; try { await api(`/api/mods/${encodeURIComponent(mod.name)}`, { method: "DELETE" }); setMessage(`${mod.name} uninstalled.`); await load(); } catch (e) { const text = e instanceof Error ? e.message : "Uninstall failed."; setMessage(text); if (role === "owner" && text.toLowerCase().includes("dependents") && window.confirm(`${text}\n\nForce uninstall and disable dependents?`)) await mutate(`/api/mods/${encodeURIComponent(mod.name)}?force=true`, { method: "DELETE" }, `${mod.name} forcibly uninstalled.`); } }
  async function bulkUpdate() { const names = updates.filter(x => x.updateAvailable).map(x => x.name); const check = await preflight("bulk-update", names); if (!canMutate || !names.length || check?.blockers.length || !window.confirm(`Update ${names.length} mod(s) atomically?`)) return; await mutate("/api/mods/bulk-update", { method: "POST", body: JSON.stringify({ names, confirm: true }) }, `${names.length} mod(s) updated.`); }
  async function update(mod: Mod) { const check = await preflight("update", [mod.name]); if (!canMutate || check?.blockers.length || !window.confirm(`Update ${mod.name} and required dependencies?`)) return; await mutate(`/api/mods/${encodeURIComponent(mod.name)}/update`, { method: "POST" }, `${mod.name} updated.`); }
  async function saveProfile() { const name = profileName.trim(); if (!name) return; const saved = await mutate("/api/mods/profiles", { method: "POST", body: JSON.stringify({ name, mods: installed.map(m => ({ name: m.name, version: m.version, enabled: m.enabled })) }) }, `Profile “${name}” saved.`); if (saved) setProfileName(""); }
  async function applyProfile(profile: ModProfile) { const check = await preflight("profile-apply", profile.mods.map(m => m.name)); if (!canMutate || check?.blockers.length || !window.confirm(`Apply profile ${profile.name}? Missing pinned versions will be downloaded.`)) return; await mutate(`/api/mods/profiles/${encodeURIComponent(profile.name)}/apply`, { method: "POST" }, `Profile “${profile.name}” applied.`); }
  async function toggle(mod: Mod) { const check = await preflight(mod.enabled ? "disable" : "enable", [mod.name]); if (!check?.blockers.length && window.confirm(`${mod.enabled ? "Disable" : "Enable"} ${mod.name}?`)) await mutate(`/api/mods/${encodeURIComponent(mod.name)}/enabled/${!mod.enabled}`, { method: "POST" }, `${mod.name} ${mod.enabled ? "disabled" : "enabled"}.`); }
  const filteredVisible = installed.filter(mod => filter === "all" || filter === "enabled" && mod.enabled || filter === "disabled" && !mod.enabled || filter === "local" && mod.source === "local" || filter === "portal" && mod.source !== "local");
  const installedVisible = filteredVisible.filter(mod => `${mod.name} ${mod.version}`.toLowerCase().includes(installedQuery.toLowerCase())).sort((a, b) => installedSort === "name" ? a.name.localeCompare(b.name) : b.version.localeCompare(a.version, undefined, { numeric: true }));
  const installedPageSize = 8; const installedPageCount = Math.max(1, Math.ceil(installedVisible.length / installedPageSize)); const installedPageItems = installedVisible.slice((installedPage - 1) * installedPageSize, installedPage * installedPageSize);
  const visible = installedPageItems;
  useEffect(() => { setInstalledPage(current => Math.min(current, installedPageCount)); }, [installedPageCount]);
  const portalVisible = results.filter(mod => `${mod.title ?? ""} ${mod.name}`.toLowerCase().includes(portalFilter.toLowerCase())).sort((a, b) => portalSort === "name" ? (a.title ?? a.name).localeCompare(b.title ?? b.name) : (b.latest_release?.version ?? "").localeCompare(a.latest_release?.version ?? ""));
  const portalPageSize = 6; const portalPageCount = Math.max(1, Math.ceil(portalVisible.length / portalPageSize)); const portalPageItems = portalVisible.slice((portalPage - 1) * portalPageSize, portalPage * portalPageSize);
  return <div className="space-y-5"><InstalledModsControls query={installedQuery} setQuery={value => { setInstalledQuery(value); setInstalledPage(1); }} sort={installedSort} setSort={value => { setInstalledSort(value as typeof installedSort); setInstalledPage(1); }} page={installedPage} setPage={setInstalledPage} pageCount={installedPageCount} count={installedVisible.length} />
    {recovery?.pending && <Card className="border border-red-500/50 bg-red-950/30"><p className="font-semibold text-red-200">Mod recovery required</p><p className="mt-1 text-sm text-red-300">{recovery.message}</p><p className="mt-1 text-xs text-red-200/70">The next safe mod operation will restore the previous transaction. Quarantined files: {recovery.quarantinedFiles.length}.</p></Card>}
    <Card className="space-y-3"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="font-semibold">Mod Portal</h2><p className="text-xs text-zinc-500">เลือกหลายรายการเพื่อ install พร้อม dependency</p></div>{selectedResults.length > 0 && <Button size="sm" onClick={() => void installSelected()} disabled={!canMutate || Boolean(installing)}>Install selected ({selectedResults.length})</Button>}</div><form onSubmit={search} className="flex flex-wrap gap-2"><input className="min-w-[12rem] flex-1" placeholder="Search mods" value={query} onChange={event => setQuery(event.target.value)} /><Button type="submit" disabled={searching || !query.trim()}>{searching ? "Searching…" : <><Search className="mr-2" size={16} />Search</>}</Button></form>{results.length > 0 && <div className="flex flex-wrap gap-2"><input placeholder="Filter results" value={portalFilter} onChange={event => { setPortalFilter(event.target.value); setPortalPage(1); }} /><select value={portalSort} onChange={event => { setPortalSort(event.target.value as typeof portalSort); setPortalPage(1); }}><option value="name">Sort: name</option><option value="version">Sort: latest version</option></select><span className="self-center text-xs text-zinc-500">{portalVisible.length} result(s)</span></div>}{searchError && <p className="rounded bg-red-950 p-2 text-sm text-red-300">{searchError}</p>}{!searching && !searchError && query.trim() && !results.length && <p className="text-sm text-zinc-400">No mods found for “{query}”.</p>}{portalPageItems.map(mod => { const checked = selectedResults.includes(mod.name); return <div key={mod.name} className="rounded border border-zinc-800 p-3"><div className="flex items-start gap-3"><input type="checkbox" checked={checked} disabled={!canMutate || Boolean(installing)} onChange={() => setSelectedResults(current => checked ? current.filter(name => name !== mod.name) : [...current, mod.name])} /><div className="min-w-0 flex-1 grow-0 shrink-0"><div className="flex items-center justify-between gap-2"><p className="font-medium">{mod.title ?? mod.name}</p>{mod.latest_release?.version && <span className="text-xs text-zinc-500">{mod.latest_release.version}</span>}</div><p className="mb-2 text-xs text-zinc-400">{mod.summary || "No summary provided."}</p>{canMutate && <Button size="sm" onClick={() => void install(mod.name)} disabled={Boolean(installing)}>{installing === mod.name ? "Installing…" : "Install only this"}</Button>}</div></div></div>; })}{results.length > 0 && <div className="flex items-center justify-between border-t border-zinc-800 pt-3"><Button size="sm" variant="outline" disabled={portalPage <= 1} onClick={() => setPortalPage(page => page - 1)}>Previous</Button><span className="text-xs text-zinc-500">Page {portalPage} / {portalPageCount}</span><Button size="sm" variant="outline" disabled={portalPage >= portalPageCount} onClick={() => setPortalPage(page => page + 1)}>Next</Button></div>}<div className="flex flex-wrap items-center gap-2 border-t border-zinc-800 pt-3"><input type="file" accept=".zip" onChange={event => setFile(event.target.files?.[0])} /><Button size="sm" variant="secondary" disabled={!file || !canMutate} onClick={() => void upload()}><Upload className="mr-2" size={15} />Upload local zip</Button></div></Card>
    <Card><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><h2 className="font-semibold">Installed</h2><div className="flex flex-wrap gap-2"><select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">All sources/status</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option><option value="portal">Portal</option><option value="local">Local</option></select><Button size="sm" variant="outline" onClick={() => void checkUpdates()} disabled={checking}>{checking ? "Checking…" : "Check updates"}</Button>{canMutate && <Button size="sm" disabled={!updates.some(x => x.updateAvailable)} onClick={() => void bulkUpdate()}>Update all safely</Button>}</div></div>{message && <p className="mb-3 rounded bg-amber-950 p-2 text-sm text-amber-200">{message}</p>}{preview && <div className={`mb-3 rounded border p-3 text-sm ${preview.blockers.length ? "border-red-500/50 bg-red-950/30" : "border-emerald-500/50 bg-emerald-950/20"}`}><p className="font-semibold">Preflight: {preview.operation}</p>{preview.warnings.map(w => <p key={w} className="text-amber-300">Warning: {w}</p>)}{preview.blockers.map(b => <p key={b} className="text-red-300">Blocked: {b}</p>)}{!preview.blockers.length && <p className="text-emerald-300">Ready. {preview.requiresBackup ? "A save backup will be created automatically." : "No save backup is needed."}</p>}</div>}{!canMutate && <p className="mb-3 text-xs text-zinc-500">Mod changes require owner/admin access and a stopped server.</p>}{visible.length ? <div className="space-y-2">{visible.map(mod => { const updateInfo = updates.find(item => item.name.toLowerCase() === mod.name.toLowerCase()); return <div key={mod.name} className="rounded border border-zinc-800 p-3 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><span>{mod.name} <span className="text-zinc-500">{mod.version}</span> <span className="ml-2 rounded bg-zinc-800 px-2 py-0.5 text-xs text-zinc-400">{mod.source ?? "portal"}</span></span>{canMutate && <div className="flex gap-2">{updateInfo?.updateAvailable && <Button size="sm" onClick={() => void update(mod)}>Update</Button>}<Button size="sm" variant={mod.enabled ? "secondary" : "outline"} onClick={() => void toggle(mod)}>{mod.enabled ? "Disable" : "Enable"}</Button><Button size="sm" variant="destructive" onClick={() => void uninstall(mod)}><Trash2 size={15} /></Button></div>}</div>{mod.factorioVersionRequirement && <p className="mt-2 text-xs text-zinc-400">Factorio requirement: {mod.factorioVersionRequirement}</p>}{updateInfo?.missingDependencies.length ? <p className="mt-2 text-xs text-amber-300">Missing dependencies: {updateInfo.missingDependencies.join(", ")}</p> : mod.dependencies?.length ? <p className="mt-2 text-xs text-zinc-500">Dependencies: {mod.dependencies.join(", ")}</p> : null}{mod.sha256 && <p className="mt-1 truncate text-xs text-zinc-600">SHA-256: {mod.sha256}</p>}</div>; })}</div> : <p className="text-sm text-zinc-400">No mods match this filter.</p>}</Card>
    <Card className="space-y-3 lg:col-span-2"><div className="flex flex-wrap items-center justify-between gap-2"><h2 className="font-semibold">Pinned profiles</h2>{canMutate && <div className="flex gap-2"><input placeholder="Profile name" value={profileName} onChange={e => setProfileName(e.target.value)} /><Button size="sm" onClick={() => void saveProfile()} disabled={!profileName.trim()}>Save current</Button></div>}</div>{profiles.length ? <div className="space-y-2">{profiles.map(profile => <div key={profile.name} className="flex flex-wrap items-center justify-between gap-2 rounded border border-zinc-800 p-3 text-sm"><span>{profile.name} <span className="text-zinc-500">({profile.mods.length} pinned versions)</span></span>{canMutate && <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => void applyProfile(profile)}>Apply profile</Button><Button size="sm" variant="destructive" onClick={() => { if (window.confirm(`Delete profile ${profile.name}?`)) void mutate(`/api/mods/profiles/${encodeURIComponent(profile.name)}`, { method: "DELETE" }, `Profile “${profile.name}” deleted.`); }}>Delete</Button></div>}</div>)}</div> : <p className="text-sm text-zinc-400">No saved profiles.</p>}</Card>
  </div>;
}

function InstalledModsControls({ query, setQuery, sort, setSort, page, setPage, pageCount, count }: { query: string; setQuery: (value: string) => void; sort: "name" | "version"; setSort: (value: string) => void; page: number; setPage: (value: number) => void; pageCount: number; count: number }) {
  return <Card className="space-y-3"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="font-semibold">Installed mods</h2><p className="text-xs text-zinc-500">{count} mod(s) · filter, sort, and browse pages below</p></div><div className="flex flex-wrap gap-2"><input placeholder="Filter by name/version" value={query} onChange={event => setQuery(event.target.value)} /><select value={sort} onChange={event => setSort(event.target.value)}><option value="name">Sort: name</option><option value="version">Sort: version</option></select></div></div>{pageCount > 1 && <div className="flex items-center justify-between border-t border-zinc-800 pt-2"><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</Button><span className="text-xs text-zinc-500">Page {page} / {pageCount}</span><Button size="sm" variant="outline" disabled={page >= pageCount} onClick={() => setPage(page + 1)}>Next</Button></div>}</Card>;
}

type BackupMetadata = { id: string; fileName: string; sourceSave: string; length: number; sha256: string; createdAtUtc: string; updatedAtUtc: string };
function Saves({ action, role, status }: { action: Action; role?: Me["role"]; status?: Status }) { const [file, setFile] = useState<File>(); const [name, setName] = useState(""); const [saves, setSaves] = useState<string[]>([]); const [backups, setBackups] = useState<BackupMetadata[]>([]); const [error, setError] = useState(""); const owner = role === "owner"; const canMutate = (role === "owner" || role === "admin") && status?.state === "stopped"; const load = useCallback(async () => { try { const [nextSaves, nextBackups] = await Promise.all([api<string[]>("/api/saves"), api<BackupMetadata[]>("/api/backups")]); setSaves(nextSaves); setBackups(nextBackups); setError(""); } catch (e) { setError(e instanceof Error ? e.message : "Could not load saves and backups."); } }, []); useEffect(() => { void load(); }, [load]); async function upload() { if (!file || !canMutate) return; const form = new FormData(); form.append("file", file); if (await action("/api/saves/upload", { method: "POST", body: form })) { setFile(undefined); await load(); } } function download(id: string) { window.open(`/api/backups/${encodeURIComponent(id)}/download`, "_blank", "noopener"); } async function restore(backup: BackupMetadata) { if (!owner || !window.confirm(`Restore ${backup.fileName} to ${backup.sourceSave}? The current save will be replaced.`)) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}/restore`, { method: "POST", body: JSON.stringify({ confirm: true }) })) await load(); } async function rename(backup: BackupMetadata) { const next = window.prompt("New backup filename (.zip)", backup.fileName); if (!next || next === backup.fileName) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}`, { method: "PATCH", body: JSON.stringify({ name: next }) })) await load(); } async function remove(backup: BackupMetadata) { if (!window.confirm(`Delete ${backup.fileName}?`)) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}`, { method: "DELETE" })) await load(); } return <div className="grid gap-5 lg:grid-cols-2">{error && <p className="rounded bg-red-950 p-3 text-sm text-red-300 lg:col-span-2">{error}</p>}<Card className="space-y-3"><h2 className="font-semibold">Saves</h2><div className="flex gap-2"><input placeholder="New map name" value={name} onChange={event => setName(event.target.value)} /><Button variant="secondary" onClick={() => void action("/api/saves/create", { method: "POST", body: JSON.stringify({ name }) }).then(load)} disabled={!name || !canMutate}>Create</Button></div><input type="file" accept=".zip" onChange={event => setFile(event.target.files?.[0])} /><Button onClick={() => void upload()} disabled={!file || !canMutate}><Save className="mr-2" size={16} />Upload</Button>{!canMutate && <p className="text-xs text-zinc-500">Save changes require owner/admin access and a stopped server.</p>}<div className="space-y-2">{saves.map(save => <div key={save} className="flex items-center justify-between rounded border border-zinc-800 p-2 text-sm"><span>{save}</span><Button size="sm" variant="outline" disabled={!canMutate} onClick={() => void action(`/api/saves/select/${encodeURIComponent(save)}`)}>Use</Button></div>)}{!saves.length && <p className="text-sm text-zinc-400">No saves uploaded yet.</p>}</div></Card><Card><h2 className="mb-3 font-semibold">Backups</h2><Button variant="secondary" disabled={!canMutate} onClick={() => void action("/api/saves/backup").then(load)}><FolderArchive className="mr-2" size={16} />Create backup</Button><div className="mt-4 space-y-2">{backups.length ? backups.map(backup => <div key={backup.id} className="rounded border border-zinc-800 p-2 text-sm"><div className="flex items-center justify-between"><span className="truncate">{backup.fileName}</span><div className="flex gap-1"><Button size="sm" variant="outline" onClick={() => download(backup.id)}><Download size={15} /></Button>{owner && <><Button size="sm" variant="outline" onClick={() => void rename(backup)}>Rename</Button><Button size="sm" variant="destructive" onClick={() => void remove(backup)}><Trash2 size={15} /></Button><Button size="sm" variant="outline" disabled={!canMutate} onClick={() => void restore(backup)}><ArchiveRestore size={15} /></Button></>}</div></div><p className="mt-1 text-xs text-zinc-500">{backup.sourceSave} · {backup.length.toLocaleString()} bytes · {backup.createdAtUtc ? new Date(backup.createdAtUtc).toLocaleString() : "unknown"}</p><p className="truncate text-xs text-zinc-600">SHA-256: {backup.sha256}</p></div>) : <p className="text-sm text-zinc-400">No backups available.</p>}</div></Card></div>; }

function Players({ action, role }: { action: Action; role?: Me["role"] }) { const [kind, setKind] = useState("admins"); const [name, setName] = useState(""); const [players, setPlayers] = useState<string[]>([]); const [live, setLive] = useState<LivePlayer[]>([]); const [message, setMessage] = useState(""); const [listError, setListError] = useState(""); const [listLoading, setListLoading] = useState(true); const canMutate = role === "owner" || role === "admin"; const load = useCallback(async () => { setListLoading(true); try { setPlayers(await api<string[]>(`/api/players/${kind}`)); setListError(""); } catch (e) { setListError(e instanceof Error ? e.message : "Could not load player list."); } finally { setListLoading(false); } }, [kind]); const loadLive = useCallback(() => { void api<LivePlayer[]>("/api/live-players").then(setLive).catch(e => setMessage(e instanceof Error ? e.message : "Live players unavailable.")); }, []); useEffect(() => { void load(); }, [load]); useEffect(() => { loadLive(); const timer = window.setInterval(loadLive, 10000); return () => window.clearInterval(timer); }, [loadLive]); async function control(path: string, body: object, prompt: string) { if (!window.confirm(prompt)) return; await action(path, { method: "POST", body: JSON.stringify(body) }); loadLive(); } return <div className="grid gap-5 lg:grid-cols-2"><Card className="space-y-4"><h2 className="font-semibold">Online players</h2>{message && <p className="rounded bg-amber-950 p-2 text-sm text-amber-300">{message}</p>}<div className="space-y-2">{live.map(player => <div key={player.name} className="flex items-center justify-between rounded border border-zinc-800 p-3 text-sm"><span>{player.name}</span>{canMutate && <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => void control("/api/live-players/kick", { playerName: player.name }, `Kick ${player.name}?`)}>Kick</Button><Button size="sm" variant="destructive" onClick={() => void control("/api/live-players/ban", { playerName: player.name, reason: "Other" }, `Ban ${player.name}?`)}>Ban</Button></div>}</div>)}{!live.length && <p className="text-sm text-zinc-400">No online players or live control is unavailable.</p>}</div><div className="flex gap-2"><input placeholder="Chat message" value={message.startsWith("RCON") ? "" : message} onChange={event => setMessage(event.target.value)} /><Button disabled={!canMutate || !message.trim()} onClick={() => void control("/api/live-chat", { message }, "Send this chat message?")}>Send chat</Button></div></Card><Card className="max-w-xl space-y-4"><h2 className="font-semibold">Player lists</h2><select value={kind} onChange={event => setKind(event.target.value)}><option value="admins">Admins</option><option value="whitelist">Whitelist</option><option value="bans">Bans</option></select>{canMutate && <div className="flex gap-2"><input placeholder="Factorio player name" value={name} onChange={event => setName(event.target.value)} /><Button onClick={() => void action(`/api/players/${kind}`, { method: "POST", body: JSON.stringify({ playerName: name }) }).then(success => { if (success) { setName(""); void load(); } })} disabled={!name}>Add</Button></div>}{listError && <p className="text-sm text-red-300">{listError}</p>}<div className="space-y-2">{listLoading ? <p className="text-sm text-zinc-400">Loading player list…</p> : players.length ? players.map(player => <div key={player} className="flex items-center justify-between rounded border border-zinc-800 p-3 text-sm"><span>{player}</span>{canMutate && <Button size="sm" variant="destructive" onClick={() => void action(`/api/players/${kind}/${encodeURIComponent(player)}`, { method: "DELETE" }).then(load)}><Trash2 size={15} /></Button>}</div>) : <p className="text-sm text-zinc-400">This list is empty.</p>}</div></Card></div>; }
